export const GUIDES = [{"slug":"client-downloads","title":"客户端下载与系统选择：v2rayN、v2rayNG、Clash Verge Rev、Hiddify","summary":"按 Windows、Android、iPhone、macOS 与 Linux 选择 v2rayN、v2rayNG、Clash Verge Rev、Hiddify 或小火箭，从官方入口核对安装包和系统架构。","keywords":["翻墙软件下载","科学上网工具","clash下载","v2rayn下载","v2rayng下载","小火箭下载","hiddify","hiddify下载","clash verge rev"],"items":["v2rayn","v2rayng","clash-verge-rev","shadowrocket","hiddify"],"sections":[{"heading":"按操作系统缩小选择","paragraphs":["v2rayN 的当前项目面向 Windows、Linux 和 macOS；v2rayNG 面向 Android。Clash Verge Rev 也是桌面客户端，项目说明列出 Windows、macOS 与 Linux。","Hiddify 的官方项目列出 Android、iOS、Windows、macOS 和 Linux，并提供各平台下载入口。它基于 sing-box，支持订阅链接及多种配置格式；仍需按当前版本核对具体字段和系统要求。"],"bullets":["桌面设备：从 v2rayN 或 Clash Verge Rev 的项目页进入 Releases。","安卓设备：v2rayNG 的 APK 来自它自己的发布页。","Apple 设备：Shadowrocket 的开发者入口是 App Store，按商店兼容性列表核对设备。"],"sources":[{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"v2rayNG Android 项目","url":"https://github.com/2dust/v2rayNG"},{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"},{"label":"Shadowrocket 开发者 App Store 页面","url":"https://apps.apple.com/us/app/shadowrocket/id932747118"},{"label":"Hiddify 官方项目与平台列表","url":"https://github.com/hiddify/hiddify-app"}]},{"heading":"安装包要同时匹配系统和架构","paragraphs":["同一个发布页可能同时提供 x64、ARM64、安装包、便携包和源代码压缩包。文件名里的系统与架构决定用途；Source code 压缩包供构建使用，不能等同于已经打包的客户端。"],"bullets":["先确认操作系统版本和处理器架构，再对照该版本的发布说明。","v2rayN 的发布文件说明还区分内核与运行环境是否随包提供。","页面名称相似不等于维护者相同，下载前对照仓库所有者和正式发布入口。"],"sources":[{"label":"v2rayN 发布文件说明","url":"https://github.com/2dust/v2rayN/wiki/Release-files-introduction"},{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"}]},{"heading":"下载完成后还缺哪些资料","paragraphs":["客户端负责管理配置并调用内核；配置则描述使用哪个服务器、什么协议以及怎样分流。只拿到客户端安装包，还不足以判断能否完成连接。"],"bullets":["准备客户端与内核的准确版本。","确认手里是单节点分享链接、订阅地址，还是完整配置文件。","把缺失的参数列出来，交给自己的 AI 根据对应官方文档继续核对。"],"sources":[{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"},{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"Shadowrocket 开发者 App Store 页面","url":"https://apps.apple.com/us/app/shadowrocket/id932747118"}]}],"faq":[{"question":"Windows、Mac 和安卓分别用哪个客户端？","answer":"v2rayN 和 Clash Verge Rev 面向 Windows、macOS 与 Linux，v2rayNG 面向 Android。Hiddify 的官方项目覆盖 Android、iOS、Windows、macOS 与 Linux。先按系统缩小选择，再对照对应发布页的处理器架构与系统要求。","sources":[{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"v2rayNG Android 项目","url":"https://github.com/2dust/v2rayNG"},{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"},{"label":"Hiddify 官方项目与平台列表","url":"https://github.com/hiddify/hiddify-app"}],"url":"https://fanqiang.guide/guides/client-downloads.html#question-1"},{"question":"v2rayN、v2rayNG 和 Clash 的官方下载在哪里？","answer":"v2rayN 与 v2rayNG 分别从 2dust 名下的同名 GitHub 仓库进入 Releases；Clash Verge Rev 从 clash-verge-rev/clash-verge-rev 项目进入发布页。“Clash”还用于其他项目名称，下载前应确认具体客户端和维护者。","sources":[{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"v2rayNG Android 项目","url":"https://github.com/2dust/v2rayNG"},{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"}],"url":"https://fanqiang.guide/guides/client-downloads.html#question-2"},{"question":"下载页里的 x64、ARM64 和 Source code 应该怎么区分？","answer":"客户端的 x64、ARM64 标记用于区分处理器架构，Windows、macOS、Linux 标记用于区分系统。Source code 是源码压缩包，和可运行的客户端发布包用途不同；v2rayN 的发布文件说明还区分便携包、安装包与随包提供的内核。","sources":[{"label":"v2rayN 发布文件说明","url":"https://github.com/2dust/v2rayN/wiki/Release-files-introduction"},{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"}],"url":"https://fanqiang.guide/guides/client-downloads.html#question-3"},{"question":"客户端装好了，是不是就已经有节点了？","answer":"客户端安装包提供软件，节点参数和订阅地址提供连接配置。v2rayN 将订阅地址、协议分享格式和内部格式单独说明；下载软件以后，还需要与你所用客户端相符的配置资料。","sources":[{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"}],"url":"https://fanqiang.guide/guides/client-downloads.html#question-4"}],"url":"https://fanqiang.guide/guides/client-downloads.html","search":"客户端下载与系统选择:v2rayn、v2rayng、clash verge rev、hiddify 按 windows、android、iphone、macos 与 linux 选择 v2rayn、v2rayng、clash verge rev、hiddify 或小火箭,从官方入口核对安装包和系统架构。 翻墙软件下载 科学上网工具 clash下载 v2rayn下载 v2rayng下载 小火箭下载 hiddify hiddify下载 clash verge rev windows、mac 和安卓分别用哪个客户端? v2rayn、v2rayng 和 clash 的官方下载在哪里? 下载页里的 x64、arm64 和 source code 应该怎么区分? 客户端装好了,是不是就已经有节点了?"},{"slug":"ladder-vpn-proxy","title":"梯子、VPN 和代理有什么区别？科学上网新手选择指南","summary":"“梯子”是口语泛称，不是协议或软件；VPN、代理、客户端、节点和订阅属于不同层次。先确认设备、需要覆盖的流量范围及持有的配置类型，再选择相应工具。","keywords":["梯子","梯子推荐","翻墙梯子","科学上网梯子","vpn和代理区别","代理工具","科学上网工具","翻墙软件"],"items":["vpn","openvpn","wireguard-tools","v2rayn","clash-verge-rev","shadowrocket","concept-tun"],"sections":[{"heading":"梯子、VPN、代理、客户端和节点分别是什么","paragraphs":["“梯子”是中文网络中的口语泛称，可能指 VPN 服务、代理客户端、节点服务或整套路由器方案，本身不是固定协议。VPN 通常在设备与远端网络之间建立虚拟网络通道；代理则按照应用、系统代理或路由规则转发被选中的连接。","v2rayN、Clash Verge Rev、Shadowrocket 等主要是客户端或客户端项目；客户端负责读取配置并调用内核，节点提供服务器连接参数，订阅则用于取得一组节点或完整配置。安装客户端不等于已经拥有节点。"],"bullets":["VPN、代理和“梯子”不是三个可以直接互换的产品名称。","系统显示 VPN 图标，不能单独证明底层使用的是哪种协议或配置方式。","客户端、代理内核、节点与订阅应分别记录，不能只用一个软件名称概括全部链路。"],"sources":[{"label":"MDN Proxy server 术语说明","url":"https://developer.mozilla.org/en-US/docs/Glossary/Proxy_server"},{"label":"NIST VPN 术语定义","url":"https://csrc.nist.gov/glossary/term/virtual_private_network"},{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"},{"label":"Shadowrocket 开发者 App Store 页面","url":"https://apps.apple.com/us/app/shadowrocket/id932747118"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}]},{"heading":"新手按设备、覆盖范围和配置类型选择","paragraphs":["先确认 Windows、macOS、Linux、Android、iPhone 还是路由器，再从对应项目或应用商店的正式入口选择客户端。随后确认只需处理单个应用、整台设备，还是希望多台家庭设备共用规则。","最后辨认手中的输入是单节点分享链接、订阅地址、完整 YAML 或 JSON 配置，还是 HTTP/SOCKS 地址列表。相同协议可能由不同客户端支持，但完整配置中的分组、规则和 DNS 字段未必通用。"],"bullets":["单台电脑或手机通常先从设备客户端开始，安装和排错范围更小。","需要多台固定设备共用规则时，再评估路由器方案。","导入成功只说明客户端读到了内容，不代表服务器当前可达或全部流量已经按预期处理。"],"sources":[{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"},{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"},{"label":"Shadowrocket 开发者 App Store 页面","url":"https://apps.apple.com/us/app/shadowrocket/id932747118"}]},{"heading":"客户端、内核和实际流量要分层检查","paragraphs":["客户端提供配置管理界面，Mihomo、Xray、sing-box 等内核负责解释配置并处理流量。排查时应同时记录客户端、内核、系统和输入类型，再区分失败发生在导入、内核启动、服务器连接、DNS 还是路由阶段。","TUN 或系统代理开关处于启用状态，不能单独证明每个应用的所有连接都经过代理；实际结果还受系统权限、路由、DNS、IPv4、IPv6 和应用行为影响。"],"bullets":["下载软件时核对项目所有者、正式发布入口、系统和处理器架构。","未知代理可能接触连接元数据及未被端到端加密的内容，不能仅凭“免费”或“付费”判断可信度。","没有同一设备、网络与时间下的可复现实测，不按 VPN 或代理的名称给出速度排名。"],"sources":[{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"},{"label":"sing-box 官方文档","url":"https://sing-box.sagernet.org/"},{"label":"Xray 官方中文文档","url":"https://xtls.github.io/"},{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"}]}],"faq":[{"question":"梯子就是 VPN 吗？","answer":"不是。“梯子”是口语泛称，可能指商业 VPN、代理客户端、节点服务或路由器方案；VPN 是其中一种技术或产品形态，两者不能直接画等号。","sources":[{"label":"MDN Proxy server 术语说明","url":"https://developer.mozilla.org/en-US/docs/Glossary/Proxy_server"},{"label":"NIST VPN 术语定义","url":"https://csrc.nist.gov/glossary/term/virtual_private_network"},{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"},{"label":"Shadowrocket 开发者 App Store 页面","url":"https://apps.apple.com/us/app/shadowrocket/id932747118"}],"url":"https://fanqiang.guide/guides/ladder-vpn-proxy.html#question-1"},{"question":"VPN 和代理哪个速度更快？","answer":"仅凭技术名称不能判断速度。服务器位置、网络路径、协议、拥塞、设备性能和规则都会影响结果；没有同一环境下的可复现实测，就不应给出固定速度排名。","sources":[{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"},{"label":"sing-box 官方文档","url":"https://sing-box.sagernet.org/"},{"label":"Xray 官方中文文档","url":"https://xtls.github.io/"}],"url":"https://fanqiang.guide/guides/ladder-vpn-proxy.html#question-2"},{"question":"Clash、v2rayN 和小火箭都是 VPN 吗？","answer":"这些名称通常指客户端或相关项目，它们读取配置并调用相应内核。平台可能借助系统 VPN 接口处理流量，但界面中的 VPN 标识不能代替对客户端、内核和协议的具体判断。","sources":[{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"},{"label":"Shadowrocket 开发者 App Store 页面","url":"https://apps.apple.com/us/app/shadowrocket/id932747118"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}],"url":"https://fanqiang.guide/guides/ladder-vpn-proxy.html#question-3"},{"question":"客户端安装好以后还需要节点或订阅吗？","answer":"通常仍需要兼容的节点、订阅或完整配置。客户端是软件，节点和订阅提供连接参数；程序安装成功、配置导入成功和服务器连接成功是三项不同结果。","sources":[{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"}],"url":"https://fanqiang.guide/guides/ladder-vpn-proxy.html#question-4"},{"question":"一台电脑能用的配置，手机也能直接用吗？","answer":"不一定。需要同时核对手机客户端、配置格式、协议和版本。单个节点参数可能可以迁移，完整配置中的规则、DNS 和平台字段则未必通用。","sources":[{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"},{"label":"sing-box 官方文档","url":"https://sing-box.sagernet.org/"}],"url":"https://fanqiang.guide/guides/ladder-vpn-proxy.html#question-5"}],"url":"https://fanqiang.guide/guides/ladder-vpn-proxy.html","search":"梯子、vpn 和代理有什么区别?科学上网新手选择指南 “梯子”是口语泛称,不是协议或软件;vpn、代理、客户端、节点和订阅属于不同层次。先确认设备、需要覆盖的流量范围及持有的配置类型,再选择相应工具。 梯子 梯子推荐 翻墙梯子 科学上网梯子 vpn和代理区别 代理工具 科学上网工具 翻墙软件 梯子就是 vpn 吗? vpn 和代理哪个速度更快? clash、v2rayn 和小火箭都是 vpn 吗? 客户端安装好以后还需要节点或订阅吗? 一台电脑能用的配置,手机也能直接用吗?"},{"slug":"airport-subscription-nodes","title":"机场、订阅和节点是什么？Clash 与 V2Ray 新手说明","summary":"“机场”是网络社区对一类配置或节点服务的口语称呼；节点是一份服务器连接参数，订阅是客户端读取一组节点或完整配置的地址或文件。导入成功不等于节点当前可用。","keywords":["机场","机场订阅","节点订阅","clash订阅","v2ray订阅","订阅节点","节点是什么","机场节点"],"items":["sub-store","subconverter","sub-web","v2rayn","shadowrocket","protocol-shadowsocks","protocol-vmess","protocol-vless","protocol-trojan"],"sections":[{"heading":"机场、订阅、节点和客户端的关系","paragraphs":["“机场”是网络社区对一类配置或节点服务的口语称呼，不是标准技术名称。节点是一份服务器连接参数；订阅是客户端用来取得一组节点或完整配置的地址或文件；客户端负责读取配置并调用内核建立连接。","常见链路可以理解为“配置来源或服务—订阅—客户端—节点—远端连接”。其中每一层都可以独立变化：一个订阅可能包含多个节点，一个节点也可以通过单独的分享链接导入，同一订阅则不一定适合所有客户端。"],"bullets":["订阅不是代理协议，协议和参数位于订阅返回的具体内容中。","客户端解析成功不等于远端服务器当前可达。","订阅地址如果包含账户令牌或访问凭据，应像密码一样保管。"],"sources":[{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"},{"label":"Shadowsocks SIP002 分享链接规范","url":"https://shadowsocks.org/doc/sip002.html"},{"label":"Shadowsocks SIP008 在线配置规范","url":"https://shadowsocks.org/doc/sip008.html"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}]},{"heading":"怎样识别单节点、订阅、配置文件和二维码","paragraphs":["ss、vmess、vless、trojan 等 URI 通常表达单节点参数；HTTPS 地址可能是订阅接口、配置文件或普通网页；YAML 和 JSON 可能保存节点列表或完整配置；IP、端口列表则可能属于 HTTP/SOCKS 代理资料。","二维码只承载文本，里面可以是单节点 URI、订阅地址、配置链接或普通网页。应先识别解码后的内容，再判断目标客户端是否支持，而不是根据二维码图片或文件后缀猜测用途。"],"bullets":["修改文件后缀不会把一种配置转换成另一种格式。","Base64 只是一种编码外观，仍需查看解码后的实际内容。","HTTP/SOCKS 地址列表不能仅凭“免费代理”四个字当成 Clash 或 V2Ray 订阅。"],"sources":[{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"},{"label":"Shadowsocks SIP002 分享链接规范","url":"https://shadowsocks.org/doc/sip002.html"},{"label":"Shadowsocks SIP008 在线配置规范","url":"https://shadowsocks.org/doc/sip008.html"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}]},{"heading":"导入、连接与订阅转换要分别判断","paragraphs":["订阅无法使用时，依次检查地址是否能读取、返回内容是否符合预期、客户端能否解析、内核是否支持协议字段、节点是否可达，以及路由和 DNS 是否命中。把这些阶段合并成“订阅不能用”，会丢失定位所需的信息。","输入与目标客户端格式不一致时可以评估 Sub-Store、subconverter 或 sub-web 等项目。转换结果能被解析，只说明格式检查通过；节点、分组、规则和 DNS 语义是否保留，仍需逐项对照。"],"bullets":["免费或付费只描述获取方式，不能直接证明速度、安全性或持续时间。","来源访问、格式解析和用户设备连接测试应分别记录。","历史日期页引用的上游链接可能继续变化，不能自动视为全部原始节点的不可变备份。"],"sources":[{"label":"Sub-Store 项目","url":"https://github.com/sub-store-org/Sub-Store"},{"label":"subconverter 项目","url":"https://github.com/tindy2013/subconverter"},{"label":"sub-web 项目","url":"https://github.com/CareyWang/sub-web"},{"label":"按日期查看免费代理与节点资料","url":"https://github.com/JasperYubo/Fanqiang-Guide/tree/main/free-proxies"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}]}],"faq":[{"question":"机场是一个客户端吗？","answer":"不是。“机场”通常指提供节点或订阅的一类服务，具体含义没有统一标准。v2rayN、Clash Verge Rev、Shadowrocket 等才是客户端或客户端项目。","sources":[{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"},{"label":"Shadowrocket 开发者 App Store 页面","url":"https://apps.apple.com/us/app/shadowrocket/id932747118"}],"url":"https://fanqiang.guide/guides/airport-subscription-nodes.html#question-1"},{"question":"一个订阅就是一个节点吗？","answer":"不是。订阅通常返回一组节点或一份完整配置，节点则是一份具体连接参数。订阅也可能只返回少量内容，因此应查看实际响应而不是按名称推断。","sources":[{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"},{"label":"Shadowsocks SIP002 分享链接规范","url":"https://shadowsocks.org/doc/sip002.html"},{"label":"Shadowsocks SIP008 在线配置规范","url":"https://shadowsocks.org/doc/sip008.html"}],"url":"https://fanqiang.guide/guides/airport-subscription-nodes.html#question-2"},{"question":"Clash 订阅可以直接导入 v2rayN 吗？","answer":"不能只看订阅名称判断。需要检查实际返回格式、其中的协议，以及目标客户端和内核版本。格式不匹配时可能需要转换，但转换后仍要核对丢失或改变的字段。","sources":[{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"},{"label":"subconverter 项目","url":"https://github.com/tindy2013/subconverter"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}],"url":"https://fanqiang.guide/guides/airport-subscription-nodes.html#question-3"},{"question":"二维码一定是小火箭节点吗？","answer":"不是。二维码可以承载单节点链接、订阅地址、配置链接或普通网页。应先识别其中的文本和响应内容，再决定使用哪个客户端处理。","sources":[{"label":"Shadowsocks SIP002 分享链接规范","url":"https://shadowsocks.org/doc/sip002.html"},{"label":"Shadowsocks SIP008 在线配置规范","url":"https://shadowsocks.org/doc/sip008.html"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"}],"url":"https://fanqiang.guide/guides/airport-subscription-nodes.html#question-4"},{"question":"为什么订阅导入成功后仍然不能连接？","answer":"导入成功只说明客户端读取并解析了某种内容。还需检查内核对协议字段的支持、节点当前可达性、路由、DNS 和系统权限，不能把解析结果当作连接证据。","sources":[{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"},{"label":"sing-box 官方文档","url":"https://sing-box.sagernet.org/"},{"label":"Xray 官方中文文档","url":"https://xtls.github.io/"}],"url":"https://fanqiang.guide/guides/airport-subscription-nodes.html#question-5"},{"question":"订阅链接可以公开发给别人帮忙看吗？","answer":"不建议公开发送。订阅地址可能包含账户令牌或访问凭据。排错时应隐藏敏感参数，只提供返回格式、客户端、版本和具体错误阶段。","sources":[{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"},{"label":"Sub-Store 项目","url":"https://github.com/sub-store-org/Sub-Store"}],"url":"https://fanqiang.guide/guides/airport-subscription-nodes.html#question-6"}],"url":"https://fanqiang.guide/guides/airport-subscription-nodes.html","search":"机场、订阅和节点是什么?clash 与 v2ray 新手说明 “机场”是网络社区对一类配置或节点服务的口语称呼;节点是一份服务器连接参数,订阅是客户端读取一组节点或完整配置的地址或文件。导入成功不等于节点当前可用。 机场 机场订阅 节点订阅 clash订阅 v2ray订阅 订阅节点 节点是什么 机场节点 机场是一个客户端吗? 一个订阅就是一个节点吗? clash 订阅可以直接导入 v2rayn 吗? 二维码一定是小火箭节点吗? 为什么订阅导入成功后仍然不能连接? 订阅链接可以公开发给别人帮忙看吗?"},{"slug":"free-nodes","title":"免费节点与订阅来源：Clash、V2Ray 和每日日期归档","summary":"每日资料通过固定文件夹进入，再选择日期文件。先辨认节点、订阅和 HTTP/SOCKS 代理的格式；资料收录与解析结果不等于连接可用性。","keywords":["clash免费节点","v2ray免费节点","免费节点订阅","免费代理","免费节点"],"items":["v2rayn","v2rayng","subconverter","sub-store"],"sections":[{"heading":"每日资料从哪里看","paragraphs":["打开“按日期查看免费代理与节点资料”文件夹，按文件名选择日期。页面记录的是当日收录的来源与检查结果，便于对照不同日期的资料。"],"bullets":["首页使用固定文件夹入口，无须记住每天的文件名。","阅读日期页中的来源项目、资料格式和核对说明。","历史页里的上游链接可能继续更新；日期页不等于当时所有原始节点的完整备份。"],"sources":[{"label":"按日期查看免费代理与节点资料","url":"https://github.com/JasperYubo/Fanqiang-Guide/tree/main/free-proxies"}]},{"heading":"节点、订阅和普通代理列表怎样区分","paragraphs":["单个分享 URI 描述一个服务器配置；订阅地址指向客户端可以读取的配置集合。HTTP 或 SOCKS 的地址与端口列表又是另一类输入，不能只凭“免费代理”四个字互相替代。"],"bullets":["通用 Base64 节点列表、Clash YAML 和 JSON 配置不是同一种格式。","Shadowsocks SIP002 定义单节点分享链接，SIP008 则定义含服务器数组的在线 JSON 配置。","目标客户端是否支持该格式，必须结合版本和文档确认。"],"sources":[{"label":"Shadowsocks SIP002 分享链接规范","url":"https://shadowsocks.org/doc/sip002.html"},{"label":"Shadowsocks SIP008 在线配置规范","url":"https://shadowsocks.org/doc/sip008.html"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"},{"label":"按日期查看免费代理与节点资料","url":"https://github.com/JasperYubo/Fanqiang-Guide/tree/main/free-proxies"}]},{"heading":"日期新、条目多，分别说明什么","paragraphs":["日期说明资料的收录或检查时间；条目数说明按页面规则解析到的数量。它们都不能直接回答某个节点在你的网络里能否连接、速度如何或能持续多久。"],"bullets":["不同来源可能有重复项目，数量不能直接视为独立服务器总数。","页面标注的格式解析和来源访问检查，与用户端连接测试应分别阅读。","免费来源也可能变更内容；使用前由自己的 AI 核对来源、格式和必要参数。"],"sources":[{"label":"按日期查看免费代理与节点资料","url":"https://github.com/JasperYubo/Fanqiang-Guide/tree/main/free-proxies"}]}],"faq":[{"question":"Clash 和 V2Ray 免费节点在哪里按日期找？","answer":"Fanqiang Guide 的 free-proxies 文件夹按日期提供免费代理与节点来源记录。选择日期文件，可以查看当日收录的来源项目、资料格式和检查记录，再按客户端需要辨认节点列表、Clash YAML 或其他配置。","sources":[{"label":"按日期查看免费代理与节点资料","url":"https://github.com/JasperYubo/Fanqiang-Guide/tree/main/free-proxies"}],"url":"https://fanqiang.guide/guides/free-nodes.html#question-1"},{"question":"免费节点、订阅地址和 HTTP/SOCKS 代理列表有什么区别？","answer":"单节点分享链接描述一份服务器配置，订阅地址用于读取一组配置，HTTP/SOCKS 列表则通常记录代理地址与端口。例如 Shadowsocks 的 SIP002 定义单节点分享链接，SIP008 定义在线 JSON 服务器列表；选择资料时要匹配客户端实际接受的格式。","sources":[{"label":"Shadowsocks SIP002 分享链接规范","url":"https://shadowsocks.org/doc/sip002.html"},{"label":"Shadowsocks SIP008 在线配置规范","url":"https://shadowsocks.org/doc/sip008.html"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"},{"label":"按日期查看免费代理与节点资料","url":"https://github.com/JasperYubo/Fanqiang-Guide/tree/main/free-proxies"}],"url":"https://fanqiang.guide/guides/free-nodes.html#question-2"},{"question":"今天更新的免费节点，就代表现在都能用吗？","answer":"免费节点日期页记录的是资料收录或检查时间，节点数量记录的是页面所述规则下的解析结果。来源访问、格式解析与用户设备上的连接测试是不同结果；当前网络能否连接、速度与稳定性，需要相应实测证据。","sources":[{"label":"按日期查看免费代理与节点资料","url":"https://github.com/JasperYubo/Fanqiang-Guide/tree/main/free-proxies"}],"url":"https://fanqiang.guide/guides/free-nodes.html#question-3"},{"question":"以前日期的节点页面，是当时全部节点的备份吗？","answer":"Fanqiang Guide 的历史日期页保留当日来源与检查记录，不等于全部原始节点内容的备份。日期页引用的上游链接可能继续更新，因此回看旧日期时，应区分当日记录和链接当前返回的内容。","sources":[{"label":"按日期查看免费代理与节点资料","url":"https://github.com/JasperYubo/Fanqiang-Guide/tree/main/free-proxies"}],"url":"https://fanqiang.guide/guides/free-nodes.html#question-4"}],"url":"https://fanqiang.guide/guides/free-nodes.html","search":"免费节点与订阅来源:clash、v2ray 和每日日期归档 每日资料通过固定文件夹进入,再选择日期文件。先辨认节点、订阅和 http/socks 代理的格式;资料收录与解析结果不等于连接可用性。 clash免费节点 v2ray免费节点 免费节点订阅 免费代理 免费节点 clash 和 v2ray 免费节点在哪里按日期找? 免费节点、订阅地址和 http/socks 代理列表有什么区别? 今天更新的免费节点,就代表现在都能用吗? 以前日期的节点页面,是当时全部节点的备份吗?"},{"slug":"subscription-conversion","title":"订阅转换怎么选：Sub-Store、subconverter 与 sub-web 的区别","summary":"订阅转换处理格式与字段。Sub-Store 偏向订阅管理，subconverter 提供格式转换，sub-web 提供前端界面；输出仍需与目标客户端逐项核对。","keywords":["订阅转换","substore","sub store","subconverter","机场订阅转换"],"items":["sub-store","subconverter","sub-web","v2rayn","mihomo"],"sections":[{"heading":"三个项目各自做什么","paragraphs":["Sub-Store 提供订阅管理能力；subconverter 负责在不同订阅格式间转换；sub-web 是订阅转换的 Web 前端。界面与实际执行转换的服务应分别辨认。"],"bullets":["管理多份来源、组合输出：查看 Sub-Store 的当前功能。","需要指定来源与目标格式：查看 subconverter 的支持范围。","看到 sub-web 界面时，还要知道它使用哪个转换后端。"],"sources":[{"label":"Sub-Store 项目","url":"https://github.com/sub-store-org/Sub-Store"},{"label":"subconverter 项目","url":"https://github.com/tindy2013/subconverter"},{"label":"sub-web 项目","url":"https://github.com/CareyWang/sub-web"}]},{"heading":"先写清输入和目标","paragraphs":["转换任务至少需要来源格式、目标客户端及版本。文件扩展名、订阅名称或“通用”标签都不足以表达全部兼容条件；协议、传输方式和规则能力也会影响结果。"],"bullets":["输入：单节点分享 URI、通用节点列表，还是完整配置。","目标：客户端名称、内核、版本和接受的格式。","期望保留：节点名称、协议参数、分组、规则和 DNS 设置。"],"sources":[{"label":"subconverter 项目","url":"https://github.com/tindy2013/subconverter"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}]},{"heading":"转换成功以后看什么","paragraphs":["输出能被解析，说明格式检查通过；它不证明所有语义都保留，也不证明服务器可达。节点字段与完整的路由、DNS 配置需要分别对照。"],"bullets":["检查节点数量与被过滤项目，不把过滤当成新增节点。","对照目标格式无法表达的字段，列明差异。","订阅更新后仍应复核输出，不能用一次结果保证以后都相同。"],"sources":[{"label":"subconverter 项目","url":"https://github.com/tindy2013/subconverter"},{"label":"Sub-Store 项目","url":"https://github.com/sub-store-org/Sub-Store"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}]}],"faq":[{"question":"Clash 订阅转换可以用什么工具？","answer":"subconverter 提供订阅格式转换，Sub-Store 提供订阅管理，sub-web 提供转换的网页界面。选择项目时应明确原始输入、目标客户端与内核版本；网页前端的名称还不能说明实际由哪个后端处理转换。","sources":[{"label":"subconverter 项目","url":"https://github.com/tindy2013/subconverter"},{"label":"Sub-Store 项目","url":"https://github.com/sub-store-org/Sub-Store"},{"label":"sub-web 项目","url":"https://github.com/CareyWang/sub-web"}],"url":"https://fanqiang.guide/guides/subscription-conversion.html#question-1"},{"question":"把订阅交给自己的 AI 转换，需要提供哪些信息？","answer":"订阅转换需要原始输入的类型、目标客户端及版本，以及要保留的节点、分组、规则和 DNS 设置。单节点 URI、节点列表与完整配置是不同输入；这些信息能让自己的 AI 对照转换器和目标内核文档判断可保留的内容。","sources":[{"label":"subconverter 项目","url":"https://github.com/tindy2013/subconverter"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}],"url":"https://fanqiang.guide/guides/subscription-conversion.html#question-2"},{"question":"订阅文件改成 YAML 后，为什么还是导不进 Clash？","answer":"Mihomo 读取的是符合配置文档的结构与字段，修改文件后缀不会转换内容。原始节点列表或其他客户端配置需要按目标格式处理，再核对协议参数、分组、规则与 DNS 字段；YAML 后缀本身不说明配置是否合格。","sources":[{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"},{"label":"subconverter 项目","url":"https://github.com/tindy2013/subconverter"}],"url":"https://fanqiang.guide/guides/subscription-conversion.html#question-3"},{"question":"订阅转换成功后，原来的规则和 DNS 会都保留吗？","answer":"订阅转换的输出能被解析，只能说明它通过了相应格式检查。节点字段、分组、路由和 DNS 的表达方式可能不同，需要分别对照目标内核；转换结果应列出保留、改变和无法表达的内容，而不是只给一个“成功”。","sources":[{"label":"subconverter 项目","url":"https://github.com/tindy2013/subconverter"},{"label":"Sub-Store 项目","url":"https://github.com/sub-store-org/Sub-Store"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}],"url":"https://fanqiang.guide/guides/subscription-conversion.html#question-4"}],"url":"https://fanqiang.guide/guides/subscription-conversion.html","search":"订阅转换怎么选:sub-store、subconverter 与 sub-web 的区别 订阅转换处理格式与字段。sub-store 偏向订阅管理,subconverter 提供格式转换,sub-web 提供前端界面;输出仍需与目标客户端逐项核对。 订阅转换 substore sub store subconverter 机场订阅转换 clash 订阅转换可以用什么工具? 把订阅交给自己的 ai 转换,需要提供哪些信息? 订阅文件改成 yaml 后,为什么还是导不进 clash? 订阅转换成功后,原来的规则和 dns 会都保留吗?"},{"slug":"shadowrocket-platforms","title":"Shadowrocket 小火箭支持哪些设备：iPhone、Mac、安卓与 Windows","summary":"Shadowrocket 的开发者商店页面列出 Apple 平台。搜索“安卓版”或“Windows 版”时，先确认项目身份，再按设备选择其他客户端。","keywords":["小火箭下载","shadowrocket android","shadowrocket windows","shadowrocket mac","小火箭安卓版"],"items":["shadowrocket","v2rayng","v2rayn","clash-verge-rev"],"sections":[{"heading":"官方商店目前列出的平台","paragraphs":["本次核对的 Shadowrocket App Store 页面包含 iPhone、iPad、Mac、Apple TV 与 Apple Vision。兼容条件分别列为 iOS 13、iPadOS 13、macOS 10.15、tvOS 17 和 visionOS 1 或更新版本。"],"bullets":["下载入口核对应用名称、开发者 Shadow Launch Technology Limited 和商店页面。","不同设备的界面与功能细节仍应以当前版本说明为准。"],"sources":[{"label":"Shadowrocket 开发者 App Store 页面","url":"https://apps.apple.com/us/app/shadowrocket/id932747118"}]},{"heading":"安卓和 Windows 搜索结果怎样判断","paragraphs":["开发者的上述入口没有列出 Android 或 Windows 版本。名称里出现 Shadowrocket、小火箭或者相似图标，不能单独作为官方版本的依据。"],"bullets":["Android 可查看 v2rayNG 项目。","Windows 可查看 v2rayN、Clash Verge Rev；这属于选择另一款客户端。","跨客户端迁移时，重新核对协议、订阅格式和配置字段，不能只换安装包。"],"sources":[{"label":"Shadowrocket 开发者 App Store 页面","url":"https://apps.apple.com/us/app/shadowrocket/id932747118"},{"label":"v2rayNG Android 项目","url":"https://github.com/2dust/v2rayNG"},{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"}]},{"heading":"应用、配置和服务分别是什么","paragraphs":["Shadowrocket 是规则代理工具。应用负责读取配置和处理流量；节点参数说明连接目标，订阅则提供一组可取得的配置。购买或安装应用不等于获得这些服务器资源。"],"bullets":["选软件：看设备兼容性和需要的配置能力。","选输入格式：分清节点 URI、订阅地址、规则文件。","判断连接结果：还需要结合自己的配置与网络环境。"],"sources":[{"label":"Shadowrocket 开发者 App Store 页面","url":"https://apps.apple.com/us/app/shadowrocket/id932747118"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"}]}],"faq":[{"question":"小火箭有安卓或 Windows 版吗？","answer":"Shadowrocket 的开发者 App Store 页面列出 Apple 平台，没有列出 Android 或 Windows 下载。安卓可查看 v2rayNG，Windows 可查看 v2rayN 或 Clash Verge Rev；这些是独立客户端，不是小火箭的同名版本。","sources":[{"label":"Shadowrocket 开发者 App Store 页面","url":"https://apps.apple.com/us/app/shadowrocket/id932747118"},{"label":"v2rayNG Android 项目","url":"https://github.com/2dust/v2rayNG"},{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"}],"url":"https://fanqiang.guide/guides/shadowrocket-platforms.html#question-1"},{"question":"小火箭官方在哪里下载，怎么认准应用？","answer":"Shadowrocket 的官方商店入口是 App Store 上应用 ID 为 932747118 的页面，开发者为 Shadow Launch Technology Limited。核对应用名称、开发者与商店兼容性，比只认“小火箭”字样或图标更能区分同名软件。","sources":[{"label":"Shadowrocket 开发者 App Store 页面","url":"https://apps.apple.com/us/app/shadowrocket/id932747118"}],"url":"https://fanqiang.guide/guides/shadowrocket-platforms.html#question-2"},{"question":"小火箭能在 Mac 上用吗？","answer":"Shadowrocket 的 App Store 兼容性列表包含 Mac。具体 macOS 要求应以该商店页面为准；Mac 与 iPhone 的界面、导入方式和配置效果仍需按各自版本核对，商店兼容性不等于两端所有功能完全一致。","sources":[{"label":"Shadowrocket 开发者 App Store 页面","url":"https://apps.apple.com/us/app/shadowrocket/id932747118"}],"url":"https://fanqiang.guide/guides/shadowrocket-platforms.html#question-3"}],"url":"https://fanqiang.guide/guides/shadowrocket-platforms.html","search":"shadowrocket 小火箭支持哪些设备:iphone、mac、安卓与 windows shadowrocket 的开发者商店页面列出 apple 平台。搜索“安卓版”或“windows 版”时,先确认项目身份,再按设备选择其他客户端。 小火箭下载 shadowrocket android shadowrocket windows shadowrocket mac 小火箭安卓版 小火箭有安卓或 windows 版吗? 小火箭官方在哪里下载,怎么认准应用? 小火箭能在 mac 上用吗?"},{"slug":"shadowrocket-qr","title":"小火箭节点二维码与订阅二维码：先分清里面装的是什么","summary":"二维码承载文本，可能是单节点 URI、订阅地址、规则配置链接或普通网页。扫码识别、配置导入和实际连接是三个不同结果。","keywords":["小火箭节点二维码","shadowrocket二维码","小火箭二维码","shadowrocket配置","小火箭订阅二维码"],"items":["shadowrocket","v2rayn","sub-store","subconverter"],"sections":[{"heading":"二维码不是一种代理协议","paragraphs":["先辨认二维码解码后的内容，再讨论如何交给客户端。图片外观不能证明里面是节点还是订阅；即使以 HTTPS 开头，也要确认它指向配置集合、规则文件还是网页。"],"bullets":["单节点 URI：例如 Shadowsocks SIP002 定义的 ss 协议分享格式。","在线配置：例如 SIP008 定义由 HTTPS 取得的 JSON 服务器数组。","以上是两种规范的区别，不代表 Shadowrocket 自动支持每一种规范或变体。"],"sources":[{"label":"Shadowsocks SIP002 分享链接规范","url":"https://shadowsocks.org/doc/sip002.html"},{"label":"Shadowsocks SIP008 在线配置规范","url":"https://shadowsocks.org/doc/sip008.html"},{"label":"Shadowrocket 开发者 App Store 页面","url":"https://apps.apple.com/us/app/shadowrocket/id932747118"}]},{"heading":"单个节点与订阅为什么不同","paragraphs":["一个单节点分享 URI 描述的是一份服务器参数；订阅则需要客户端按地址读取内容。把单个 URI 做成二维码，不会因此产生可自动更新的订阅来源。"],"bullets":["判断更新能力，要看客户端是否保存了订阅来源及其当前返回内容。","协议字段、插件参数或客户端专有字段，可能影响跨客户端识别。","Base64 是编码方式，本身不构成加密或兼容性保证。"],"sources":[{"label":"Shadowsocks SIP002 分享链接规范","url":"https://shadowsocks.org/doc/sip002.html"},{"label":"Shadowsocks SIP008 在线配置规范","url":"https://shadowsocks.org/doc/sip008.html"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"}]},{"heading":"扫码后应该分三层看结果","paragraphs":["二维码被识别，只说明文本被读出。配置被导入，还要看字段是否被目标版本接受。最终是否连接成功，需要用户设备与网络的实际结果。"],"bullets":["识别层：解码内容属于哪一种资料。","配置层：目标客户端是否接受这种格式与字段。","连接层：由用户自己的 AI 根据实际现象继续核对，不能从前两层代推。"],"sources":[{"label":"Shadowsocks SIP002 分享链接规范","url":"https://shadowsocks.org/doc/sip002.html"},{"label":"Shadowrocket 开发者 App Store 页面","url":"https://apps.apple.com/us/app/shadowrocket/id932747118"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"}]}],"faq":[{"question":"小火箭节点二维码和订阅地址有什么区别？","answer":"小火箭节点二维码可以承载一个服务器的分享 URI，订阅地址则用于取得一组配置；二维码也可以承载订阅地址。区分两者要看二维码里的文本及链接实际提供的内容，而不是图片外观。","sources":[{"label":"Shadowsocks SIP002 分享链接规范","url":"https://shadowsocks.org/doc/sip002.html"},{"label":"Shadowsocks SIP008 在线配置规范","url":"https://shadowsocks.org/doc/sip008.html"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"}],"url":"https://fanqiang.guide/guides/shadowrocket-qr.html#question-1"},{"question":"小火箭能扫出二维码，为什么还是导入失败？","answer":"小火箭识别二维码只完成了文本读取，导入还需要内容符合客户端支持的格式与字段。单节点 URI、在线配置和普通网页链接用途不同；判断原因需要原始内容类型、客户端版本与导入错误，不能只看扫码是否成功。","sources":[{"label":"Shadowsocks SIP002 分享链接规范","url":"https://shadowsocks.org/doc/sip002.html"},{"label":"Shadowsocks SIP008 在线配置规范","url":"https://shadowsocks.org/doc/sip008.html"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"},{"label":"Shadowrocket 开发者 App Store 页面","url":"https://apps.apple.com/us/app/shadowrocket/id932747118"}],"url":"https://fanqiang.guide/guides/shadowrocket-qr.html#question-2"},{"question":"把一个节点做成二维码后，会自动更新吗？","answer":"单节点二维码仍然保存那份服务器分享信息，不会因为变成图片就成为订阅来源。订阅更新依赖客户端保存的来源地址及该地址返回的配置；判断能否更新，应先分清二维码装的是单节点 URI 还是在线配置入口。","sources":[{"label":"Shadowsocks SIP002 分享链接规范","url":"https://shadowsocks.org/doc/sip002.html"},{"label":"Shadowsocks SIP008 在线配置规范","url":"https://shadowsocks.org/doc/sip008.html"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"}],"url":"https://fanqiang.guide/guides/shadowrocket-qr.html#question-3"},{"question":"二维码里是 HTTPS 链接，就一定是订阅吗？","answer":"HTTPS 链接说明访问方式，不能单独说明二维码内容是订阅。该地址可能返回服务器列表、规则文件或普通网页；例如 SIP008 对在线配置规定了 JSON 服务器数组，因此仍要对照响应内容与客户端接受的格式。","sources":[{"label":"Shadowsocks SIP008 在线配置规范","url":"https://shadowsocks.org/doc/sip008.html"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"}],"url":"https://fanqiang.guide/guides/shadowrocket-qr.html#question-4"}],"url":"https://fanqiang.guide/guides/shadowrocket-qr.html","search":"小火箭节点二维码与订阅二维码:先分清里面装的是什么 二维码承载文本,可能是单节点 uri、订阅地址、规则配置链接或普通网页。扫码识别、配置导入和实际连接是三个不同结果。 小火箭节点二维码 shadowrocket二维码 小火箭二维码 shadowrocket配置 小火箭订阅二维码 小火箭节点二维码和订阅地址有什么区别? 小火箭能扫出二维码,为什么还是导入失败? 把一个节点做成二维码后,会自动更新吗? 二维码里是 https 链接,就一定是订阅吗?"},{"slug":"router-guide","title":"路由器翻墙与科学上网怎么选？OpenWrt、OpenClash 与梅林指南","summary":"路由器方案适合统一管理多台设备，但安装插件不会自动让所有流量按预期处理。先分清硬件、固件、插件、代理内核和配置，再选择 OpenWrt 或华硕梅林路线。","keywords":["路由器翻墙","路由器科学上网","openwrt翻墙","openclash教程","梅林翻墙","华硕路由器翻墙","旁路由科学上网","路由器代理"],"items":["openwrt","openclash","passwall2","mihomo","xray-core","sing-box","asuswrt-merlin","asuswrt-merlin-gnuton","fancyss","merlinclash"],"sections":[{"heading":"先判断是否需要路由器方案","paragraphs":["路由器方案把流量规则放在家庭或办公网络的网关上，适合需要统一管理多台固定设备，或电视、游戏机等不方便安装客户端的场景。只有一台电脑或手机时，设备客户端通常更容易安装、停用和排错。","安装路由器插件不会自动让所有设备按预期联网。实际结果仍取决于 DHCP、DNS、IPv4、IPv6、策略路由、绕过规则以及设备取得的网络参数。"],"bullets":["经常更换 Wi-Fi 或使用移动网络的设备，优先评估随设备移动的客户端。","不熟悉固件恢复和局域网排错时，先从单台设备客户端开始。","需要多台固定设备共用规则时，再评估网关集中管理的收益和维护成本。"],"sources":[{"label":"OpenWrt 用户文档","url":"https://openwrt.org/docs/guide-user/start"},{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"},{"label":"PassWall2 环境与依赖要求","url":"https://github.com/Openwrt-Passwall/openwrt-passwall2"},{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"}]},{"heading":"把硬件、固件、插件、内核和配置分开","paragraphs":["硬件层包括完整型号、硬件修订、CPU 架构、内存、存储和网口；固件层包括 OpenWrt、Asuswrt-Merlin、GNUton 构建及厂商原版固件；OpenClash、PassWall2、fancyss 和 MerlinClash 则属于不同环境下的应用或插件。","Mihomo、Xray、sing-box 等内核负责解释配置并处理流量，节点、订阅、分组、路由和 DNS 属于配置层。固件能运行、插件能安装、内核能启动和实际流量符合预期，是四项需要分别验证的结果。"],"bullets":["同一系列名称下的不同硬件修订，固件支持可能不同。","OpenWrt 软件包不能因路由器品牌相同就直接用于梅林固件。","节点协议相同，不代表 OpenClash 与 PassWall2 的完整配置可以原样互换。"],"sources":[{"label":"OpenWrt 用户文档","url":"https://openwrt.org/docs/guide-user/start"},{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"},{"label":"PassWall2 环境与依赖要求","url":"https://github.com/Openwrt-Passwall/openwrt-passwall2"},{"label":"Asuswrt-Merlin 官方支持设备表","url":"https://github.com/RMerl/asuswrt-merlin.ng/wiki/Supported-Devices"},{"label":"GNUton 构建与支持设备","url":"https://github.com/gnuton/asuswrt-merlin.ng"},{"label":"fancyss 固件环境与平台包说明","url":"https://github.com/hq450/fancyss"},{"label":"MerlinClash 项目说明","url":"https://github.com/rts600/MerlinClash/blob/main/README.md"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}]},{"heading":"OpenWrt 与华硕梅林分别怎么核对","paragraphs":["OpenWrt 路线先确认设备支持、CPU 架构、可用内存与存储、固件版本和包管理方式，再核对 OpenClash 或 PassWall2 的依赖、所用内核以及订阅或完整配置的格式。","华硕梅林路线先确认完整型号和 V1、V2、PRO 等硬件标记，再区分 Asuswrt-Merlin 原版、GNUton 构建及带软件中心的改版环境。型号出现在固件支持表中，不能代替 fancyss 或 MerlinClash 的插件适配检查。"],"bullets":["厂商原版固件即使提供 VPN 客户端，也不等于支持 OpenWrt 或梅林插件。","资源需求受协议、规则数量、DNS 功能、连接数和其他插件共同影响，不能用一个固定内存数字判断所有设备。","项目来源列为支持只证明存在相应声明，不代表本站已在该设备完成刷机、吞吐量或稳定性实测。"],"sources":[{"label":"OpenWrt 用户文档","url":"https://openwrt.org/docs/guide-user/start"},{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"},{"label":"PassWall2 环境与依赖要求","url":"https://github.com/Openwrt-Passwall/openwrt-passwall2"},{"label":"Asuswrt-Merlin 官方支持设备表","url":"https://github.com/RMerl/asuswrt-merlin.ng/wiki/Supported-Devices"},{"label":"GNUton 构建与支持设备","url":"https://github.com/gnuton/asuswrt-merlin.ng"},{"label":"fancyss 固件环境与平台包说明","url":"https://github.com/hq450/fancyss"},{"label":"MerlinClash 项目说明","url":"https://github.com/rts600/MerlinClash/blob/main/README.md"}]},{"heading":"改动前保留恢复资料并分阶段验证","paragraphs":["开始改动前应记录完整型号、当前固件版本、WAN、LAN、DHCP、DNS、IPv6 设置以及可用的管理和救援入口，并保留与当前版本对应的配置备份。","不要在没有恢复路径时同时更换固件、插件、内核、DNS 和订阅。每完成一层，只验证该层的安装、启动和网络结果，便于出现问题时回到最近一次已知可用状态。"],"bullets":["先确认有线管理地址和厂商恢复方式仍然可用。","分别测试路由器本身、普通直连设备和应使用规则的目标设备。","记录测试时间、设备、网络、配置版本和实际路径，不用一个网页能打开代替完整验证。"],"sources":[{"label":"OpenWrt 用户文档","url":"https://openwrt.org/docs/guide-user/start"},{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"},{"label":"PassWall2 环境与依赖要求","url":"https://github.com/Openwrt-Passwall/openwrt-passwall2"},{"label":"Asuswrt-Merlin 官方支持设备表","url":"https://github.com/RMerl/asuswrt-merlin.ng/wiki/Supported-Devices"},{"label":"fancyss 固件环境与平台包说明","url":"https://github.com/hq450/fancyss"},{"label":"MerlinClash 项目说明","url":"https://github.com/rts600/MerlinClash/blob/main/README.md"}]}],"faq":[{"question":"OpenWrt 和 OpenClash 是同一个东西吗？","answer":"不是。OpenWrt 是路由器操作系统或固件环境，OpenClash 是运行在 OpenWrt LuCI 环境中的客户端项目；OpenClash 还会调用 Mihomo 等组件处理配置和流量。","sources":[{"label":"OpenWrt 用户文档","url":"https://openwrt.org/docs/guide-user/start"},{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}],"url":"https://fanqiang.guide/guides/router-guide.html#question-1"},{"question":"OpenClash 和 PassWall2 应该选哪个？","answer":"两者是 OpenWrt 上的不同 LuCI 应用，配置方式、依赖和所用组件不同。应根据当前固件、设备资源、输入格式及功能需求判断，不能只按名称或界面选择。","sources":[{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"},{"label":"PassWall2 环境与依赖要求","url":"https://github.com/Openwrt-Passwall/openwrt-passwall2"}],"url":"https://fanqiang.guide/guides/router-guide.html#question-2"},{"question":"华硕梅林可以直接安装 OpenClash 吗？","answer":"OpenClash 面向 OpenWrt/LuCI 环境，梅林属于另一套固件与插件环境。梅林用户应核对对应固件、软件中心及 fancyss、MerlinClash 等项目要求。","sources":[{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"},{"label":"Asuswrt-Merlin 官方支持设备表","url":"https://github.com/RMerl/asuswrt-merlin.ng/wiki/Supported-Devices"},{"label":"fancyss 固件环境与平台包说明","url":"https://github.com/hq450/fancyss"},{"label":"MerlinClash 项目说明","url":"https://github.com/rts600/MerlinClash/blob/main/README.md"}],"url":"https://fanqiang.guide/guides/router-guide.html#question-3"},{"question":"路由器装好插件后，所有设备都会自动走代理吗？","answer":"不一定。哪些设备和连接被处理，还取决于 DHCP、DNS、IPv4、IPv6、策略路由、绕过规则及插件配置。应验证设备取得的网络参数和目标请求的实际路径。","sources":[{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"},{"label":"PassWall2 环境与依赖要求","url":"https://github.com/Openwrt-Passwall/openwrt-passwall2"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}],"url":"https://fanqiang.guide/guides/router-guide.html#question-4"},{"question":"OpenClash 的完整配置能直接给 PassWall2 用吗？","answer":"不能默认通用。两者输入方式和依赖不同；部分节点参数可能重新使用，但分组、规则、DNS 及其他完整配置字段需要按目标项目重新核对。","sources":[{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"},{"label":"PassWall2 环境与依赖要求","url":"https://github.com/Openwrt-Passwall/openwrt-passwall2"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}],"url":"https://fanqiang.guide/guides/router-guide.html#question-5"},{"question":"路由器内存越大，速度就一定越快吗？","answer":"不一定。内存影响可加载的规则和组件数量，吞吐量还受 CPU、协议、内核、连接数、网口和网络路径影响。没有同一设备及配置下的测试，不能只凭内存判断速度。","sources":[{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"},{"label":"PassWall2 环境与依赖要求","url":"https://github.com/Openwrt-Passwall/openwrt-passwall2"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}],"url":"https://fanqiang.guide/guides/router-guide.html#question-6"}],"url":"https://fanqiang.guide/guides/router-guide.html","search":"路由器翻墙与科学上网怎么选?openwrt、openclash 与梅林指南 路由器方案适合统一管理多台设备,但安装插件不会自动让所有流量按预期处理。先分清硬件、固件、插件、代理内核和配置,再选择 openwrt 或华硕梅林路线。 路由器翻墙 路由器科学上网 openwrt翻墙 openclash教程 梅林翻墙 华硕路由器翻墙 旁路由科学上网 路由器代理 openwrt 和 openclash 是同一个东西吗? openclash 和 passwall2 应该选哪个? 华硕梅林可以直接安装 openclash 吗? 路由器装好插件后,所有设备都会自动走代理吗? openclash 的完整配置能直接给 passwall2 用吗? 路由器内存越大,速度就一定越快吗?"},{"slug":"openwrt-tools","title":"OpenWrt 路由器翻墙与科学上网：OpenClash、PassWall2 与设备条件","summary":"OpenWrt 是路由器系统，OpenClash 和 PassWall2 是其应用层项目。选择工具前，要核对设备、固件版本、内存、存储、包格式及内核依赖。","keywords":["openclash教程","passwall教程","openwrt科学上网","openclash","passwall2","路由器翻墙","路由器科学上网","openwrt翻墙"],"items":["openwrt","openclash","passwall","passwall2","mihomo","sing-box","xray-core"],"sections":[{"heading":"固件、管理界面和代理内核","paragraphs":["OpenClash 是面向 OpenWrt 的 LuCI 客户端，项目说明使用 Mihomo 内核。PassWall2 也是 LuCI 应用，可按功能依赖不同代理组件。固件、插件界面和实际处理流量的内核各有版本。 PassWall 与 PassWall2 分别收录为不同项目，环境要求应按完整项目名称查阅。"],"bullets":["先确认运行的是哪一个 OpenWrt 版本或衍生固件。","再区分安装的 LuCI 应用与它调用的内核。","查错时记录三层版本，单写“装了 OpenClash”信息不足。"],"sources":[{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"},{"label":"PassWall2 环境与依赖要求","url":"https://github.com/Openwrt-Passwall/openwrt-passwall2"}]},{"heading":"按固件和架构核对安装包与依赖","paragraphs":["PassWall2 的官方 README 按 OpenWrt 的包管理器区分 IPK 与 APK 下载格式，并要求对应路由器架构及组件依赖。本次核对日期为 2026-09-13。具体设备还需结合剩余内存、存储和所用功能评估，不能用一个固定内存数字判断所有路由器。"],"bullets":["核对 CPU 架构、可用内存与剩余存储。","核对固件的包管理方式，以及插件和内核依赖。","规则规模、DNS 功能和同时启用的组件也会影响资源使用。"],"sources":[{"label":"PassWall2 环境与依赖要求","url":"https://github.com/Openwrt-Passwall/openwrt-passwall2"},{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"}]},{"heading":"订阅与配置迁移要核对什么","paragraphs":["OpenClash 所用的 Mihomo 配置，与另一客户端的完整配置不应默认互换。节点协议相同，也可能使用不同的分组、路由和 DNS 表达方式。"],"bullets":["区分节点输入、完整配置和规则提供者。","迁移时列出必须保留的设备分流与 DNS 需求。","已有路由器设置先交给自己的 AI 核对；资料中的项目支持表不等于设备实测。"],"sources":[{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"},{"label":"PassWall2 环境与依赖要求","url":"https://github.com/Openwrt-Passwall/openwrt-passwall2"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}]}],"faq":[{"question":"OpenClash 和 PassWall2 有什么区别？","answer":"OpenClash 是面向 OpenWrt、使用 Mihomo 内核的 LuCI 客户端；PassWall2 是另一款 OpenWrt LuCI 代理应用。两者的配置方式与依赖分别由各自项目说明，比较时需要同时看固件、应用与代理内核，不能只比较名称。","sources":[{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"},{"label":"PassWall2 环境与依赖要求","url":"https://github.com/Openwrt-Passwall/openwrt-passwall2"}],"url":"https://fanqiang.guide/guides/openwrt-tools.html#question-1"},{"question":"华硕梅林能直接安装 OpenClash 吗？","answer":"OpenClash 面向 OpenWrt/LuCI 环境，华硕梅林的固件和插件环境另有要求。梅林用户应查对应固件及 fancyss、MerlinClash 等插件的项目说明；路由器品牌相同不能使 OpenWrt 安装包通用。","sources":[{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"},{"label":"fancyss 固件环境与平台包说明","url":"https://github.com/hq450/fancyss"},{"label":"MerlinClash 项目说明","url":"https://github.com/rts600/MerlinClash/blob/main/README.md"}],"url":"https://fanqiang.guide/guides/openwrt-tools.html#question-2"},{"question":"PassWall2 下载应该选 IPK 还是 APK？","answer":"PassWall2 的当前官方说明按 OpenWrt 包管理器区分下载格式：使用 OPKG 的固件对应 IPK，使用 APK 包管理器的固件对应 APK。本次核对日期为 2026-09-13；还应对应路由器架构和所需依赖，不能只凭文件后缀选包。","sources":[{"label":"PassWall2 环境与依赖要求","url":"https://github.com/Openwrt-Passwall/openwrt-passwall2"}],"url":"https://fanqiang.guide/guides/openwrt-tools.html#question-3"},{"question":"OpenClash 配置可以直接给 PassWall2 用吗？","answer":"OpenClash 使用 Mihomo 配置，PassWall2 的输入与依赖由它自己的项目说明定义。迁移时需要区分节点参数和完整配置，并核对分组、路由、DNS 与设备分流需求；节点协议相同不等于完整配置能原样互换。","sources":[{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"},{"label":"PassWall2 环境与依赖要求","url":"https://github.com/Openwrt-Passwall/openwrt-passwall2"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}],"url":"https://fanqiang.guide/guides/openwrt-tools.html#question-4"}],"url":"https://fanqiang.guide/guides/openwrt-tools.html","search":"openwrt 路由器翻墙与科学上网:openclash、passwall2 与设备条件 openwrt 是路由器系统,openclash 和 passwall2 是其应用层项目。选择工具前,要核对设备、固件版本、内存、存储、包格式及内核依赖。 openclash教程 passwall教程 openwrt科学上网 openclash passwall2 路由器翻墙 路由器科学上网 openwrt翻墙 openclash 和 passwall2 有什么区别? 华硕梅林能直接安装 openclash 吗? passwall2 下载应该选 ipk 还是 apk? openclash 配置可以直接给 passwall2 用吗?"},{"slug":"asus-merlin","title":"华硕梅林路由器翻墙与科学上网：AX86U、AX58U 固件及插件","summary":"先确认完整型号与硬件修订，再区分原版 Merlin、GNUton 构建和带软件中心的改版环境。固件支持与 fancyss、MerlinClash 插件适配是两次不同的核对。","keywords":["梅林固件下载","梅林固件","merlinclash","fancyss","ax86u pro 梅林","ax58u 梅林","ac68u 梅林","华硕路由器翻墙","梅林科学上网","梅林翻墙"],"items":["asuswrt","asuswrt-merlin","asuswrt-merlin-gnuton","koolcenter-merlin-mod","koolcenter-asuswrt-mod","fancyss","merlinclash","amtm","entware"],"sections":[{"heading":"梅林不是一个通用安装包","paragraphs":["Asuswrt-Merlin 原版与 GNUton 构建各自列出设备支持范围。fancyss、MerlinClash 属于插件项目，不能用“固件能刷”代替“插件能装”的判断。"],"bullets":["固件层：记录项目名称、版本和完整设备型号。","环境层：确认是否具备目标插件要求的软件中心等条件。","插件层：再核对平台包、依赖和当前发布说明。"],"sources":[{"label":"Asuswrt-Merlin 官方支持设备表","url":"https://github.com/RMerl/asuswrt-merlin.ng/wiki/Supported-Devices"},{"label":"GNUton 构建与支持设备","url":"https://github.com/gnuton/asuswrt-merlin.ng"},{"label":"fancyss 固件环境与平台包说明","url":"https://github.com/hq450/fancyss"},{"label":"MerlinClash 项目说明","url":"https://github.com/rts600/MerlinClash/blob/main/README.md"}]},{"heading":"AX58U V1、V2 与 AC68U 的实际区别","paragraphs":["原版 Merlin 的支持表明确列出 RT-AX58U V1／RT-AX3000 V1；GNUton 项目另列 RT-AX58U V2。因此省略 V1、V2 会把不同支持分支混在一起。"],"bullets":["原版表将 RT-AC68U 的所有版本列入不再支持设备。","GNUton 列有 DSL-AC68U，DSL 与 RT 前缀不能省略。","RT-AX86U 与 RT-AX86U PRO 也应分别按完整名称核对。"],"sources":[{"label":"Asuswrt-Merlin 官方支持设备表","url":"https://github.com/RMerl/asuswrt-merlin.ng/wiki/Supported-Devices"},{"label":"GNUton 构建与支持设备","url":"https://github.com/gnuton/asuswrt-merlin.ng"}]},{"heading":"fancyss 包型与固件支持分开看","paragraphs":["fancyss 说明要求基于 Asuswrt／Merlin 且带软件中心的相应固件环境，并区分平台包与 full、lite 包型。某款设备在插件表出现，并不改变原版固件项目对它的维护状态。"],"bullets":["平台包要对照设备平台与架构，不按名称相近选择。","full、lite 的功能与空间需求不同，按项目当前说明核对。","MerlinClash 使用自己的项目说明与包来源；不要把一个插件的支持表转用给另一个。"],"sources":[{"label":"fancyss 固件环境与平台包说明","url":"https://github.com/hq450/fancyss"},{"label":"MerlinClash 项目说明","url":"https://github.com/rts600/MerlinClash/blob/main/README.md"},{"label":"Asuswrt-Merlin 官方支持设备表","url":"https://github.com/RMerl/asuswrt-merlin.ng/wiki/Supported-Devices"}]}],"faq":[{"question":"华硕梅林支持哪些型号，去哪里查？","answer":"Asuswrt-Merlin 原版的支持范围查官方 Supported Devices 表，GNUton 构建查 GNUton 自己的设备列表。型号要保留 RT/DSL 前缀及 V1、V2、PRO 等标记；固件支持和插件适配分别查各自项目，不能合并成一个通用支持结论。","sources":[{"label":"Asuswrt-Merlin 官方支持设备表","url":"https://github.com/RMerl/asuswrt-merlin.ng/wiki/Supported-Devices"},{"label":"GNUton 构建与支持设备","url":"https://github.com/gnuton/asuswrt-merlin.ng"},{"label":"fancyss 固件环境与平台包说明","url":"https://github.com/hq450/fancyss"}],"url":"https://fanqiang.guide/guides/asus-merlin.html#question-1"},{"question":"华硕 AX58U V1 和 V2 应该查哪个梅林版本？","answer":"RT-AX58U V1 在原版 Asuswrt-Merlin 支持表中，RT-AX58U V2 在 GNUton 支持列表中。硬件修订决定应查的固件分支，选下载资料时必须保留 V1、V2，不能把“AX58U”当作同一个设备。","sources":[{"label":"Asuswrt-Merlin 官方支持设备表","url":"https://github.com/RMerl/asuswrt-merlin.ng/wiki/Supported-Devices"},{"label":"GNUton 构建与支持设备","url":"https://github.com/gnuton/asuswrt-merlin.ng"}],"url":"https://fanqiang.guide/guides/asus-merlin.html#question-2"},{"question":"华硕 AC68U 现在还支持梅林吗？","answer":"原版 Asuswrt-Merlin 已把 RT-AC68U 的所有版本和硬件修订列入不再支持设备。GNUton 列出的 DSL-AC68U 是另一个完整型号，不能把它的支持声明转给 RT-AC68U；历史固件资料也应与当前维护状态分开阅读。","sources":[{"label":"Asuswrt-Merlin 官方支持设备表","url":"https://github.com/RMerl/asuswrt-merlin.ng/wiki/Supported-Devices"},{"label":"GNUton 构建与支持设备","url":"https://github.com/gnuton/asuswrt-merlin.ng"}],"url":"https://fanqiang.guide/guides/asus-merlin.html#question-3"},{"question":"路由器能刷梅林，就能装 fancyss 或 MerlinClash 吗？","answer":"梅林固件的设备支持与 fancyss、MerlinClash 的插件适配是两项判断。fancyss 项目另有固件环境、软件中心和平台包要求，MerlinClash 也有自己的说明；型号出现在固件表里，不能代替这些插件条件与实际运行结果。","sources":[{"label":"Asuswrt-Merlin 官方支持设备表","url":"https://github.com/RMerl/asuswrt-merlin.ng/wiki/Supported-Devices"},{"label":"fancyss 固件环境与平台包说明","url":"https://github.com/hq450/fancyss"},{"label":"MerlinClash 项目说明","url":"https://github.com/rts600/MerlinClash/blob/main/README.md"}],"url":"https://fanqiang.guide/guides/asus-merlin.html#question-4"}],"url":"https://fanqiang.guide/guides/asus-merlin.html","search":"华硕梅林路由器翻墙与科学上网:ax86u、ax58u 固件及插件 先确认完整型号与硬件修订,再区分原版 merlin、gnuton 构建和带软件中心的改版环境。固件支持与 fancyss、merlinclash 插件适配是两次不同的核对。 梅林固件下载 梅林固件 merlinclash fancyss ax86u pro 梅林 ax58u 梅林 ac68u 梅林 华硕路由器翻墙 梅林科学上网 梅林翻墙 华硕梅林支持哪些型号,去哪里查? 华硕 ax58u v1 和 v2 应该查哪个梅林版本? 华硕 ac68u 现在还支持梅林吗? 路由器能刷梅林,就能装 fancyss 或 merlinclash 吗?"},{"slug":"v2rayn-guide","title":"v2rayN 使用指南与工程书：版本、内核、订阅和配置","summary":"从官方发布文件开始，先匹配系统与架构，再分清内核、单节点分享链接和订阅。配置导入、内核运行与实际连接应分别判断。","keywords":["v2rayn使用教程","v2rayn教程","v2rayn下载","v2rayn订阅","v2rayn配置"],"items":["v2rayn","v2rayng","xray-core","sing-box","mihomo","concept-tun"],"sections":[{"heading":"项目与发布文件怎样对应","paragraphs":["当前 v2rayN 面向 Windows、Linux、macOS。官方发布文件说明区分系统、架构和包内组件；同一版本出现多个附件，是因为它们用途不同。"],"bullets":["版本号相同，x64 与 ARM64 仍不能混为一谈。","先核对发布文件说明，再区分便携包、安装包与运行环境。","Android 对应的是另一个项目 v2rayNG。"],"sources":[{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"v2rayN 发布文件说明","url":"https://github.com/2dust/v2rayN/wiki/Release-files-introduction"},{"label":"v2rayNG Android 项目","url":"https://github.com/2dust/v2rayNG"}]},{"heading":"内核和界面各自负责什么","paragraphs":["v2rayN 作为图形客户端管理配置，并支持调用 Xray、sing-box 等内核。界面版本与内核版本不是一个编号；某功能是否存在，要同时看所选内核及其配置。"],"bullets":["记录客户端版本、当前内核与内核版本。","导入成功只表示客户端接收了资料，后续还要判断内核运行状态。","不要从界面显示的节点名称推断协议参数已经完整。"],"sources":[{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"Xray-core 项目","url":"https://github.com/XTLS/Xray-core"}]},{"heading":"单节点分享与订阅更新","paragraphs":["官方文档区分协议标准分享格式与 v2rayN 内部格式。内部格式可以携带标准分享方案之外的字段，但不能据此保证其他客户端也能识别。"],"bullets":["单节点分享资料用于描述一个配置；订阅地址用于取得一组配置。","迁移给其他客户端前，标明原始格式与必须保留的字段。","更新订阅改变的是取回的配置，规则与本地设置是否变化需要另外核对。"],"sources":[{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"}]},{"heading":"排查时把现象分开","paragraphs":["“不能用”可能指打不开程序、无法导入、内核未运行，或者已有连接请求但没有得到预期结果。这些现象需要不同证据。"],"bullets":["程序问题：系统、架构、版本与启动错误。","配置问题：输入格式及脱敏后的解析错误。","网络行为问题：内核、路由、DNS 与具体目标的现象。"],"sources":[{"label":"v2rayN 发布文件说明","url":"https://github.com/2dust/v2rayN/wiki/Release-files-introduction"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"},{"label":"sing-box TUN 配置文档","url":"https://sing-box.sagernet.org/configuration/inbound/tun/"}]}],"faq":[{"question":"v2rayN 配置前要准备哪些资料？","answer":"v2rayN 配置需要操作系统与架构、客户端版本、所用内核，以及已有的节点分享链接、订阅地址或配置文件。官方发布说明用于核对程序包，订阅说明用于辨认输入；把这些资料交给自己的 AI，比只说“v2rayN 不能用”更容易定位下一步。","sources":[{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"v2rayN 发布文件说明","url":"https://github.com/2dust/v2rayN/wiki/Release-files-introduction"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"}],"url":"https://fanqiang.guide/guides/v2rayn-guide.html#question-1"},{"question":"v2rayN 分享的链接为什么在其他客户端导不进去？","answer":"v2rayN 同时有协议标准分享格式和内部分享格式，内部格式可以携带标准提案以外的字段。其他客户端是否能导入，取决于它接受的格式与字段；跨客户端迁移时需要辨认原始格式，而不只是复制同一段链接。","sources":[{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"}],"url":"https://fanqiang.guide/guides/v2rayn-guide.html#question-2"},{"question":"v2rayN 订阅导入了，为什么还不能连接？","answer":"v2rayN 接收订阅和内核完成连接是两个阶段。排查资料应包括当前 Xray、sing-box 等内核及版本、配置输入类型和完整错误现象，再区分程序启动、配置解析、路由或 DNS 问题；导入成功本身不能证明服务器可达。","sources":[{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"v2rayN 订阅与分享格式说明","url":"https://github.com/2dust/v2rayN/wiki/Description-of-subscription"},{"label":"Xray-core 项目","url":"https://github.com/XTLS/Xray-core"},{"label":"sing-box TUN 配置文档","url":"https://sing-box.sagernet.org/configuration/inbound/tun/"}],"url":"https://fanqiang.guide/guides/v2rayn-guide.html#question-3"}],"url":"https://fanqiang.guide/guides/v2rayn-guide.html","search":"v2rayn 使用指南与工程书:版本、内核、订阅和配置 从官方发布文件开始,先匹配系统与架构,再分清内核、单节点分享链接和订阅。配置导入、内核运行与实际连接应分别判断。 v2rayn使用教程 v2rayn教程 v2rayn下载 v2rayn订阅 v2rayn配置 v2rayn 配置前要准备哪些资料? v2rayn 分享的链接为什么在其他客户端导不进去? v2rayn 订阅导入了,为什么还不能连接?"},{"slug":"proxy-cores","title":"Mihomo、sing-box 与 Xray：代理内核、客户端和 TUN 的关系","summary":"客户端提供管理界面，内核解释配置并处理流量。协议、规则、DNS 与 TUN 是不同层面的能力，选择时要核对对应项目及版本。","keywords":["mihomo","sing box","xray","tun模式","clash内核","科学上网内核"],"items":["mihomo","sing-box","xray-core","v2rayn","clash-verge-rev","concept-tun","concept-fakeip","concept-ruleset"],"sections":[{"heading":"客户端与内核不是同一层","paragraphs":["Clash Verge Rev 项目说明使用 Mihomo；v2rayN 可以调用 Xray、sing-box 等内核。用户看到的管理界面与实际解释配置的程序可以来自不同项目。"],"bullets":["下载客户端时，同时核对它包含或调用的内核。","阅读文档时，将界面操作与内核配置字段分开。","排查问题时给出双方版本，避免只报一个应用名称。"],"sources":[{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"},{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"Xray-core 项目","url":"https://github.com/XTLS/Xray-core"}]},{"heading":"相同协议不等于相同配置文件","paragraphs":["协议用于表达与服务器通信的方式；完整配置还可能包含监听入口、路由、DNS 和规则来源。两个内核都支持某协议，不代表它们接受相同的配置结构。"],"bullets":["Mihomo 的字段以其配置文档为准。","sing-box 的 TUN 字段有明确的平台与版本条件。","跨内核迁移应检查字段语义及不支持项，而不是只替换程序名。"],"sources":[{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"},{"label":"sing-box TUN 配置文档","url":"https://sing-box.sagernet.org/configuration/inbound/tun/"},{"label":"Xray-core 项目","url":"https://github.com/XTLS/Xray-core"}]},{"heading":"TUN 与 DNS、路由一起核对","paragraphs":["TUN 涉及虚拟网络接口及流量路由。是否由它处理某个请求，要结合系统、权限、路由和 DNS 配置判断；勾选 TUN 不能单独证明所有流量都符合预期。"],"bullets":["记录操作系统、内核版本和采用的入口方式。","把域名解析与路由选择分开检查。","已有其他代理、虚拟网络或自定义路由时，先列出现状。"],"sources":[{"label":"sing-box TUN 配置文档","url":"https://sing-box.sagernet.org/configuration/inbound/tun/"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}]}],"faq":[{"question":"Xray、sing-box 和 Mihomo 的官方文档在哪里？","answer":"Xray 官方中文文档在 xtls.github.io，sing-box 官方文档在 sing-box.sagernet.org，Mihomo 配置文档在 wiki.metacubex.one。查内核字段时应使用对应项目的文档；客户端下载和界面说明则查客户端自己的项目。","sources":[{"label":"Xray 官方中文文档","url":"https://xtls.github.io/"},{"label":"sing-box 官方文档","url":"https://sing-box.sagernet.org/"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"},{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"}],"url":"https://fanqiang.guide/guides/proxy-cores.html#question-1"},{"question":"客户端和代理内核有什么区别，版本需要一样吗？","answer":"v2rayN、Clash Verge Rev 等客户端提供配置管理界面，Xray、sing-box、Mihomo 等内核负责解释配置并处理流量。客户端与内核是不同组件，版本号无需相同；需要确认客户端调用哪种内核，以及配置是否适合该内核版本。","sources":[{"label":"v2rayN 项目与下载入口","url":"https://github.com/2dust/v2rayN"},{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"},{"label":"Xray-core 项目","url":"https://github.com/XTLS/Xray-core"},{"label":"sing-box 官方文档","url":"https://sing-box.sagernet.org/"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}],"url":"https://fanqiang.guide/guides/proxy-cores.html#question-2"},{"question":"Xray、sing-box 和 Mihomo 能共用一份配置吗？","answer":"Xray、sing-box 与 Mihomo 各有自己的配置结构，支持相同协议也不代表能共用完整配置。节点、监听入口、路由和 DNS 要按目标内核分别核对；换程序或改文件后缀不会完成这些字段的迁移。","sources":[{"label":"Xray 官方中文文档","url":"https://xtls.github.io/"},{"label":"sing-box 官方文档","url":"https://sing-box.sagernet.org/"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}],"url":"https://fanqiang.guide/guides/proxy-cores.html#question-3"},{"question":"TUN 模式是做什么的，开启后所有流量都会走代理吗？","answer":"TUN 通过虚拟网络接口参与流量处理，具体哪些请求进入代理还取决于系统、权限、路由和 DNS 配置。sing-box 与 Mihomo 的相关字段应按对应版本文档核对；开关显示已启用不能单独代表每个应用的流量都符合预期。","sources":[{"label":"sing-box TUN 配置文档","url":"https://sing-box.sagernet.org/configuration/inbound/tun/"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}],"url":"https://fanqiang.guide/guides/proxy-cores.html#question-4"}],"url":"https://fanqiang.guide/guides/proxy-cores.html","search":"mihomo、sing-box 与 xray:代理内核、客户端和 tun 的关系 客户端提供管理界面,内核解释配置并处理流量。协议、规则、dns 与 tun 是不同层面的能力,选择时要核对对应项目及版本。 mihomo sing box xray tun模式 clash内核 科学上网内核 xray、sing-box 和 mihomo 的官方文档在哪里? 客户端和代理内核有什么区别,版本需要一样吗? xray、sing-box 和 mihomo 能共用一份配置吗? tun 模式是做什么的,开启后所有流量都会走代理吗?"},{"slug":"clash-projects","title":"Clash 下载与项目区别：Clash Verge Rev、原版 Verge 和 OpenClash","summary":"Clash 相关名称覆盖桌面客户端、路由器插件和内核。先确认维护者、项目状态与设备平台，再选择下载入口；相似名称不能代替来源核对。","keywords":["clash下载","clash for windows下载","clash verge rev","clash verge","openclash","clash项目"],"items":["clash-verge-rev","openclash","mihomo","clash-meta-for-android","clash-premium"],"sections":[{"heading":"先分清桌面、路由器和内核","paragraphs":["Clash Verge Rev 是桌面客户端，项目列出 Windows、macOS 与 Linux，并使用 Mihomo。OpenClash 则是 OpenWrt 的 LuCI 客户端。Mihomo 的配置文档描述内核行为，不能当作某个桌面应用的安装说明。"],"bullets":["桌面安装入口对应具体客户端项目。","路由器插件还要满足固件、架构与依赖条件。","配置资料需要标明所用内核及版本。"],"sources":[{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"},{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}]},{"heading":"原 Clash Verge 与 Rev 的维护状态","paragraphs":["zzzgydi/clash-verge 仓库页面显示已于 2023 年 11 月 3 日归档并只读。Clash Verge Rev 使用另一个维护仓库；选择它时应从 Rev 项目自己的发布入口确认版本。"],"bullets":["原仓库的历史资料不能自动当作 Rev 当前说明。","相同配置迁移后是否保留行为，仍需对照新客户端与内核。","项目有发布记录只证明项目发布了文件，不等于已在你的设备实测。"],"sources":[{"label":"原 Clash Verge 仓库归档状态","url":"https://github.com/zzzgydi/clash-verge"},{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"}]},{"heading":"搜索 Clash for Windows 时怎么辨认来源","paragraphs":["“Clash for Windows”“Clash Verge Rev”“OpenClash”是不同项目名称。下载站用熟悉的名称作栏目，不足以证明其中的文件来自原维护者。"],"bullets":["核对页面给出的仓库所有者、应用名称和原始发布地址。","不能把 Rev 直接描述为 Clash for Windows 的同名新版。","历史附件、第三方镜像与当前维护项目应分别标明来源。"],"sources":[{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"},{"label":"原 Clash Verge 仓库归档状态","url":"https://github.com/zzzgydi/clash-verge"},{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"}]}],"faq":[{"question":"Clash for Windows 和 Clash Verge Rev 是同一个软件吗？","answer":"Clash Verge Rev 有独立的项目名称、维护仓库和发布入口，应与 Clash for Windows 分别辨认。查找下载时应对应具体项目所有者，不能把 Rev 直接当作 Clash for Windows 的同名新版本。","sources":[{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"}],"url":"https://fanqiang.guide/guides/clash-projects.html#question-1"},{"question":"原版 Clash Verge 和 Clash Verge Rev 有什么区别？","answer":"原 zzzgydi/clash-verge 仓库已于 2023 年 11 月 3 日归档，Clash Verge Rev 使用独立的维护仓库。原项目的历史说明与 Rev 的当前发布资料属于不同来源，选择下载与查配置时应以所用项目为准。","sources":[{"label":"原 Clash Verge 仓库归档状态","url":"https://github.com/zzzgydi/clash-verge"},{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"}],"url":"https://fanqiang.guide/guides/clash-projects.html#question-2"},{"question":"Clash Verge Rev 和 OpenClash 应该怎么选？","answer":"Clash Verge Rev 是 Windows、macOS、Linux 桌面客户端，OpenClash 是 OpenWrt 路由器上的 LuCI 客户端。桌面电脑与路由器对应不同安装环境；即使同样使用 Mihomo，也需要分别核对配置、依赖和设备分流设置。","sources":[{"label":"Clash Verge Rev 项目","url":"https://github.com/clash-verge-rev/clash-verge-rev"},{"label":"OpenClash 项目说明","url":"https://github.com/vernesong/OpenClash"},{"label":"Mihomo 配置文档","url":"https://wiki.metacubex.one/config/"}],"url":"https://fanqiang.guide/guides/clash-projects.html#question-3"}],"url":"https://fanqiang.guide/guides/clash-projects.html","search":"clash 下载与项目区别:clash verge rev、原版 verge 和 openclash clash 相关名称覆盖桌面客户端、路由器插件和内核。先确认维护者、项目状态与设备平台,再选择下载入口;相似名称不能代替来源核对。 clash下载 clash for windows下载 clash verge rev clash verge openclash clash项目 clash for windows 和 clash verge rev 是同一个软件吗? 原版 clash verge 和 clash verge rev 有什么区别? clash verge rev 和 openclash 应该怎么选?"}];
